-- =============================================================================
-- V1__initial_schema.sql
-- Calozone · PostgreSQL 16 · Flyway
--
-- Creates the 13 core tables. Conventions applied throughout:
--   * Primary keys are uuid, generated by the database (gen_random_uuid(), core
--     since PostgreSQL 13, so no extension is needed).
--   * Instants are timestamptz in UTC. A user's "day" is local_date, computed by
--     the API in the profile timezone when the row is written. Group by local_date,
--     never by the date part of a timestamp.
--   * Rows the app writes offline carry client_uuid, unique per user. Inserts use
--     ON CONFLICT (user_id, client_uuid) DO NOTHING so retries are harmless and
--     one user can never collide with, or read back, another user's row.
--   * Editable rows carry version (optimistic locking, mapped with @Version),
--     updated_at, and deleted_at (soft delete, so deletions sync).
--   * Enumerations are text + CHECK rather than PostgreSQL enum types: adding a
--     value is a one-line constraint change in a later migration.
--   * Every foreign key has an index and an explicit ON DELETE rule. Deleting a
--     users row removes all of that user's data (GDPR erasure, roadmap 7.05).
--   * updated_at is maintained by the application, not by triggers.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- Identity
-- -----------------------------------------------------------------------------

CREATE TABLE users (
    id            uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    provider      text        NOT NULL CHECK (provider IN ('apple', 'google')),
    provider_sub  text        NOT NULL,
    email         text,
    created_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_provider_identity UNIQUE (provider, provider_sub)
);

COMMENT ON TABLE  users              IS 'One row per signed-in person. Identity only; preferences live in profiles.';
COMMENT ON COLUMN users.provider_sub IS 'The provider''s stable subject id (ID token "sub" claim). Email can change or be hidden, so it is not the key.';
COMMENT ON COLUMN users.email        IS 'As reported by the provider. May be null or an Apple private-relay address.';


CREATE TABLE profiles (
    user_id                 uuid         PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    timezone                text         NOT NULL,
    units                   text         NOT NULL DEFAULT 'kg'       CHECK (units IN ('kg', 'lb')),
    sex                     text                                     CHECK (sex IN ('male', 'female', 'other')),
    birth_year              smallint                                 CHECK (birth_year BETWEEN 1900 AND 2100),
    height_cm               numeric(5,1)                             CHECK (height_cm > 0),
    start_weight_kg         numeric(5,1)                             CHECK (start_weight_kg > 0),
    goal                    text                                     CHECK (goal IN ('build', 'cut', 'maintain')),
    philosophy              text         NOT NULL DEFAULT 'volume'   CHECK (philosophy IN ('volume', 'strength', 'hybrid')),
    autoreg_mode            text         NOT NULL DEFAULT 'advisory' CHECK (autoreg_mode IN ('off', 'advisory', 'automatic')),
    kcal_target             integer                                  CHECK (kcal_target > 0),
    protein_target_g        integer                                  CHECK (protein_target_g > 0),
    rest_default_s          integer      NOT NULL DEFAULT 90         CHECK (rest_default_s BETWEEN 0 AND 3600),
    health_consent_at       timestamptz,
    health_consent_version  text,
    created_at              timestamptz  NOT NULL DEFAULT now(),
    updated_at              timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT profiles_consent_complete
        CHECK ((health_consent_at IS NULL) = (health_consent_version IS NULL))
);

COMMENT ON TABLE  profiles                        IS 'Created at the end of onboarding. A user without a profile has not finished onboarding.';
COMMENT ON COLUMN profiles.timezone               IS 'IANA zone name (e.g. Europe/Tirane), validated with ZoneId.of() in the API. Every local_date is computed in this zone.';
COMMENT ON COLUMN profiles.units                  IS 'Display preference only. All weights are stored in kg.';
COMMENT ON COLUMN profiles.kcal_target            IS 'User override. Null means derive from goal and bodyweight.';
COMMENT ON COLUMN profiles.protein_target_g       IS 'User override. Null means derive from goal and bodyweight.';
COMMENT ON COLUMN profiles.health_consent_at      IS 'When the user gave explicit consent to process health data (GDPR Art. 9). Null = not given or withdrawn.';
COMMENT ON COLUMN profiles.health_consent_version IS 'Privacy policy version the consent applies to. A material policy change requires consent again.';


-- -----------------------------------------------------------------------------
-- Programs
-- -----------------------------------------------------------------------------

CREATE TABLE exercises (
    id                 uuid    PRIMARY KEY DEFAULT gen_random_uuid(),
    name               text    NOT NULL CHECK (length(trim(name)) > 0),
    primary_muscle     text    NOT NULL,
    secondary_muscles  text[]  NOT NULL DEFAULT '{}',
    equipment          text             CHECK (equipment IN ('barbell', 'dumbbell', 'machine', 'cable', 'bodyweight', 'other')),
    owner_id           uuid             REFERENCES users (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX exercises_catalogue_name ON exercises (lower(name)) WHERE owner_id IS NULL;
CREATE UNIQUE INDEX exercises_custom_name    ON exercises (owner_id, lower(name)) WHERE owner_id IS NOT NULL;

COMMENT ON TABLE  exercises          IS 'Built-in catalogue (owner_id null, seeded by migration) plus each user''s custom exercises.';
COMMENT ON COLUMN exercises.owner_id IS 'Null for catalogue exercises. Set for custom exercises, which only their owner can see.';


CREATE TABLE programs (
    id           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name         text        NOT NULL CHECK (length(trim(name)) > 0),
    philosophy   text        NOT NULL CHECK (philosophy IN ('volume', 'strength', 'hybrid')),
    block_weeks  smallint    NOT NULL CHECK (block_weeks BETWEEN 1 AND 52),
    starts_on    date        NOT NULL,
    active       boolean     NOT NULL DEFAULT false,
    version      integer     NOT NULL DEFAULT 1,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX        programs_user       ON programs (user_id);
CREATE UNIQUE INDEX programs_one_active ON programs (user_id) WHERE active;

COMMENT ON COLUMN programs.active IS 'At most one active program per user (programs_one_active). Switch by deactivating the old one first, in the same transaction.';


CREATE TABLE program_days (
    id          uuid     PRIMARY KEY DEFAULT gen_random_uuid(),
    program_id  uuid     NOT NULL REFERENCES programs (id) ON DELETE CASCADE,
    weekday     smallint NOT NULL CHECK (weekday BETWEEN 1 AND 7),
    label       text     NOT NULL,
    rest        boolean  NOT NULL DEFAULT false,
    CONSTRAINT program_days_one_per_weekday UNIQUE (program_id, weekday)
);

COMMENT ON COLUMN program_days.weekday IS 'ISO-8601 day of week: 1 = Monday … 7 = Sunday.';


CREATE TABLE program_exercises (
    id              uuid     PRIMARY KEY DEFAULT gen_random_uuid(),
    program_day_id  uuid     NOT NULL REFERENCES program_days (id) ON DELETE CASCADE,
    exercise_id     uuid     NOT NULL REFERENCES exercises (id)    ON DELETE CASCADE,
    order_ix        smallint NOT NULL CHECK (order_ix >= 0),
    target_sets     smallint NOT NULL CHECK (target_sets BETWEEN 1 AND 12),
    rep_low         smallint NOT NULL CHECK (rep_low  BETWEEN 1 AND 100),
    rep_high        smallint NOT NULL CHECK (rep_high BETWEEN 1 AND 100),
    rest_s          integer           CHECK (rest_s BETWEEN 0 AND 3600),
    progression     text     NOT NULL DEFAULT 'double' CHECK (progression IN ('double', 'linear', 'rir')),
    CONSTRAINT program_exercises_rep_range CHECK (rep_low <= rep_high),
    CONSTRAINT program_exercises_order UNIQUE (program_day_id, order_ix) DEFERRABLE INITIALLY DEFERRED
);

CREATE INDEX program_exercises_exercise ON program_exercises (exercise_id);

COMMENT ON COLUMN program_exercises.order_ix    IS 'Position within the day. The unique constraint is deferred so a reorder can swap positions inside one transaction.';
COMMENT ON COLUMN program_exercises.rest_s      IS 'Null means use profiles.rest_default_s.';
COMMENT ON COLUMN program_exercises.progression IS 'double = add reps to the top of the range, then load; linear = add load each session; rir = driven by reps in reserve.';


-- -----------------------------------------------------------------------------
-- Verdict
-- -----------------------------------------------------------------------------

CREATE TABLE day_verdicts (
    id             uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id        uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    local_date     date        NOT NULL,
    set_delta      smallint    NOT NULL DEFAULT 0,
    kcal_delta     integer     NOT NULL DEFAULT 0,
    reasoning      jsonb       NOT NULL CHECK (jsonb_typeof(reasoning) = 'array'),
    inputs_hash    text        NOT NULL CHECK (inputs_hash ~ '^[0-9a-f]{64}$'),
    state          text        NOT NULL DEFAULT 'issued' CHECK (state IN ('issued', 'applied', 'declined')),
    issued_at      timestamptz NOT NULL DEFAULT now(),
    decided_at     timestamptz,
    superseded_by  uuid                 REFERENCES day_verdicts (id) ON DELETE CASCADE,
    CONSTRAINT day_verdicts_not_self_superseded CHECK (superseded_by <> id),
    CONSTRAINT day_verdicts_decision_time       CHECK ((state = 'issued') = (decided_at IS NULL))
);

CREATE UNIQUE INDEX day_verdicts_live       ON day_verdicts (user_id, local_date) WHERE superseded_by IS NULL;
CREATE INDEX        day_verdicts_user_day   ON day_verdicts (user_id, local_date);
CREATE INDEX        day_verdicts_superseded ON day_verdicts (superseded_by) WHERE superseded_by IS NOT NULL;

COMMENT ON TABLE  day_verdicts               IS 'Append-only. A verdict''s numbers are never updated; a recalculation inserts a new row and points the old one at it.';
COMMENT ON COLUMN day_verdicts.reasoning     IS 'JSON array of reason objects shown on Today. Shape is versioned in the API, not the schema.';
COMMENT ON COLUMN day_verdicts.inputs_hash   IS 'SHA-256 (hex) of the canonical JSON of the inputs. Same hash = nothing that matters changed, so no new verdict.';
COMMENT ON COLUMN day_verdicts.state         IS 'User decision. Allowed moves: issued -> applied, issued -> declined. Superseded is derived from superseded_by, not stored here.';
COMMENT ON COLUMN day_verdicts.superseded_by IS 'Null = the live verdict for that day (at most one, see day_verdicts_live).';


-- -----------------------------------------------------------------------------
-- Training log
-- -----------------------------------------------------------------------------

CREATE TABLE sessions (
    id                  uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id             uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    client_uuid         uuid        NOT NULL,
    local_date          date        NOT NULL,
    program_day_id      uuid                 REFERENCES program_days (id) ON DELETE SET NULL,
    applied_verdict_id  uuid                 REFERENCES day_verdicts (id) ON DELETE SET NULL,
    started_at          timestamptz NOT NULL,
    finished_at         timestamptz,
    version             integer     NOT NULL DEFAULT 1,
    updated_at          timestamptz NOT NULL DEFAULT now(),
    deleted_at          timestamptz,
    CONSTRAINT sessions_client_uuid UNIQUE (user_id, client_uuid),
    CONSTRAINT sessions_id_user     UNIQUE (id, user_id),
    CONSTRAINT sessions_time_order  CHECK (finished_at IS NULL OR finished_at >= started_at)
);

CREATE INDEX sessions_user_day       ON sessions (user_id, local_date) WHERE deleted_at IS NULL;
CREATE INDEX sessions_program_day    ON sessions (program_day_id)      WHERE program_day_id IS NOT NULL;
CREATE INDEX sessions_applied_verdict ON sessions (applied_verdict_id) WHERE applied_verdict_id IS NOT NULL;

COMMENT ON COLUMN sessions.program_day_id     IS 'The planned day this session followed. Null for unplanned sessions or if the program was deleted.';
COMMENT ON COLUMN sessions.applied_verdict_id IS 'The verdict the user applied for this session, if any.';
COMMENT ON CONSTRAINT sessions_id_user ON sessions IS 'Target for the composite FK from set_logs, guaranteeing a set belongs to the same user as its session.';


CREATE TABLE set_logs (
    id           uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      uuid         NOT NULL,
    session_id   uuid         NOT NULL,
    client_uuid  uuid         NOT NULL,
    exercise_id  uuid         NOT NULL REFERENCES exercises (id) ON DELETE CASCADE,
    set_ix       smallint     NOT NULL CHECK (set_ix >= 0),
    reps         smallint     NOT NULL CHECK (reps BETWEEN 0 AND 100),
    load_kg      numeric(6,2) NOT NULL CHECK (load_kg >= 0),
    rir          smallint              CHECK (rir BETWEEN 0 AND 10),
    logged_at    timestamptz  NOT NULL,
    version      integer      NOT NULL DEFAULT 1,
    updated_at   timestamptz  NOT NULL DEFAULT now(),
    deleted_at   timestamptz,
    CONSTRAINT set_logs_client_uuid UNIQUE (user_id, client_uuid),
    CONSTRAINT set_logs_session FOREIGN KEY (session_id, user_id)
        REFERENCES sessions (id, user_id) ON DELETE CASCADE
);

CREATE INDEX set_logs_session       ON set_logs (session_id)                         WHERE deleted_at IS NULL;
CREATE INDEX set_logs_user_exercise ON set_logs (user_id, exercise_id, logged_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX set_logs_exercise      ON set_logs (exercise_id);

COMMENT ON COLUMN set_logs.user_id    IS 'Denormalised from sessions so ownership checks and per-user progress queries need no join. Kept consistent by the composite FK.';
COMMENT ON COLUMN set_logs.load_kg    IS 'Always kg. Converted for display using profiles.units.';
COMMENT ON COLUMN set_logs.rir        IS 'Reps in reserve as reported by the user. Null if not recorded.';
COMMENT ON COLUMN set_logs.deleted_at IS 'Soft delete. Also used for the in-session "undo last set".';


-- -----------------------------------------------------------------------------
-- Recovery and nutrition
-- -----------------------------------------------------------------------------

CREATE TABLE sleep_nights (
    id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    local_date  date        NOT NULL,
    source      text        NOT NULL CHECK (source IN ('manual', 'healthkit', 'health_connect')),
    minutes     smallint    NOT NULL CHECK (minutes BETWEEN 0 AND 1440),
    asleep_at   timestamptz,
    woke_at     timestamptz,
    intervals   jsonb                CHECK (intervals IS NULL OR jsonb_typeof(intervals) = 'array'),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT sleep_nights_one_per_source UNIQUE (user_id, local_date, source),
    CONSTRAINT sleep_nights_time_order     CHECK (woke_at IS NULL OR asleep_at IS NULL OR woke_at > asleep_at)
);

COMMENT ON TABLE  sleep_nights            IS 'One row per night per source. Writes upsert on (user_id, local_date, source); a health-app row takes precedence over a manual one when both exist.';
COMMENT ON COLUMN sleep_nights.local_date IS 'The local date of the morning the night ended.';
COMMENT ON COLUMN sleep_nights.minutes    IS 'Total time asleep, excluding awake intervals.';
COMMENT ON COLUMN sleep_nights.intervals  IS 'Raw stage intervals from the health platform, kept for later analysis. Null for manual entries.';


CREATE TABLE food_logs (
    id            uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    client_uuid   uuid         NOT NULL,
    local_date    date         NOT NULL,
    name          text         NOT NULL CHECK (length(trim(name)) > 0),
    kcal          integer      NOT NULL CHECK (kcal BETWEEN 0 AND 20000),
    protein_g     numeric(6,1) NOT NULL DEFAULT 0 CHECK (protein_g >= 0),
    carb_g        numeric(6,1) NOT NULL DEFAULT 0 CHECK (carb_g    >= 0),
    fat_g         numeric(6,1) NOT NULL DEFAULT 0 CHECK (fat_g     >= 0),
    source        text         NOT NULL CHECK (source IN ('manual', 'photo', 'saved', 'repeat')),
    confirmed_at  timestamptz  NOT NULL,
    version       integer      NOT NULL DEFAULT 1,
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    deleted_at    timestamptz,
    CONSTRAINT food_logs_client_uuid UNIQUE (user_id, client_uuid)
);

CREATE INDEX food_logs_user_day ON food_logs (user_id, local_date) WHERE deleted_at IS NULL;

COMMENT ON COLUMN food_logs.source       IS 'How the entry was made. photo = confirmed from a vision estimate; the photo itself is never stored.';
COMMENT ON COLUMN food_logs.confirmed_at IS 'When the user confirmed the entry on the device.';


CREATE TABLE saved_meals (
    id           uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    client_uuid  uuid         NOT NULL,
    name         text         NOT NULL CHECK (length(trim(name)) > 0),
    icon         text,
    kcal         integer      NOT NULL CHECK (kcal BETWEEN 0 AND 20000),
    protein_g    numeric(6,1) NOT NULL DEFAULT 0 CHECK (protein_g >= 0),
    carb_g       numeric(6,1) NOT NULL DEFAULT 0 CHECK (carb_g    >= 0),
    fat_g        numeric(6,1) NOT NULL DEFAULT 0 CHECK (fat_g     >= 0),
    times_used   integer      NOT NULL DEFAULT 0 CHECK (times_used >= 0),
    version      integer      NOT NULL DEFAULT 1,
    created_at   timestamptz  NOT NULL DEFAULT now(),
    updated_at   timestamptz  NOT NULL DEFAULT now(),
    deleted_at   timestamptz,
    CONSTRAINT saved_meals_client_uuid UNIQUE (user_id, client_uuid)
);

CREATE INDEX saved_meals_user ON saved_meals (user_id, times_used DESC) WHERE deleted_at IS NULL;

COMMENT ON COLUMN saved_meals.icon       IS 'Icon key from the app''s icon set, not an image.';
COMMENT ON COLUMN saved_meals.times_used IS 'Incremented each time the meal is logged; orders the picker.';


CREATE TABLE bodyweight (
    user_id     uuid         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    local_date  date         NOT NULL,
    kg          numeric(5,2) NOT NULL CHECK (kg BETWEEN 20 AND 400),
    updated_at  timestamptz  NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, local_date)
);

COMMENT ON TABLE bodyweight IS 'One reading per user per day. A second write for the same day replaces the first (PUT), so it is idempotent without client_uuid.';
